mapper.select:
SELECT d.name as director, a.name as actor, COUNT(DISTINCT md.movie_id) as collaborations FROM movie_directors md JOIN movie_actors ma ON md.movie_id = ma.movie_id JOIN directors d ON md.director_id = d.id JOIN actors a ON ma.actor_id = a.id
JOIN movie_genres mg ON md.movie_id = mg.movie_id
mg.genre = #{genre}
GROUP BY d.name, a.name ORDER BY collaborations DESC LIMIT #{limit}

SELECT d.name as director, a.name as actor, SUM(m.review_num) as review_sum FROM movie_directors md JOIN movie_actors ma ON md.movie_id = ma.movie_id JOIN directors d ON md.director_id = d.id JOIN actors a ON ma.actor_id = a.id JOIN movies m ON md.movie_id = m.id
JOIN movie_genres mg ON md.movie_id = mg.movie_id
mg.genre = #{genre}
GROUP BY d.name, a.name ORDER BY review_sum DESC LIMIT #{limit}
